import{_ as a,C as i,o as s,c as o,E as n,a2 as r}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"Industry Architecture Weekly 002 — Enterprise Software Is Moving from Systems of Record to Systems of Execution","description":"","frontmatter":{"title":"Industry Architecture Weekly 002 — Enterprise Software Is Moving from Systems of Record to Systems of Execution","date":"2026-08-02","column":"industry-architecture","category":"weekly","summary":"Oracle, Salesforce, and ServiceNow are embedding Agents into business objects, workflows, authority, approvals, and audit, shifting enterprise software from passive recording toward governed execution.","sources":["Oracle Fusion Agentic Applications and AI Agent Studio","Salesforce Agentforce","ServiceNow Autonomous Workforce"],"outline":"deep","cover":"/assets/covers/systems-of-record-to-execution-cover-v2.jpg"},"headers":[],"relativePath":"en/industry/2026-08-02-from-systems-of-record-to-systems-of-execution.md","filePath":"en/industry/2026-08-02-from-systems-of-record-to-systems-of-execution.md","lastUpdated":1787407830000}'),l={name:"en/industry/2026-08-02-from-systems-of-record-to-systems-of-execution.md"};function c(d,e,p,u,h,m){const t=i("ArticleCover");return s(),o("div",null,[n(t,{image:"/assets/covers/systems-of-record-to-execution-cover-v2.jpg",kicker:"Industry Architecture · Weekly 002",title:"Enterprise Software Is Moving from Systems of Record to Systems of Execution",summary:"Oracle, Salesforce, and ServiceNow embed Agents into business objects, workflows, authority, approvals, and audit.",version:"IW002",status:"Published 2026-08-02",languageHref:"/zh/industry/2026-08-02-from-systems-of-record-to-systems-of-execution",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Traditional enterprise software primarily records customers, employees, finance, assets, process state, and transaction history. Agentic enterprise software is adding a second responsibility: actively executing work inside the same data, authority, and workflow environment.</p><p>Oracle defines Fusion Agentic Applications as outcome-driven applications backed by specialized Agent teams using Fusion business objects, workflows, policies, approvals, and logged actions. Salesforce Agentforce combines enterprise data, metadata, skills, flows, and Agent execution into a digital labor platform. ServiceNow Autonomous Workforce uses role-defined AI Specialists with scope, authority, policy, traceability, and human escalation to execute enterprise work end to end.</p><p>This report’s judgment is:</p><blockquote><p>Enterprise software will not simply be replaced by a generic Agent layer outside the business system. A more likely architecture combines the System of Record with a governed System of Execution inside the same transactional context.</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>Three groups of official materials were selected:</p><ol><li><strong>Oracle Fusion Agentic Applications / AI Agent Studio:</strong> native Agent teams inheriting Fusion business objects, permissions, workflows, approvals, and audit.</li><li><strong>Salesforce Agentforce:</strong> Agents acting through Data 360, CRM metadata, skills, flows, and business logic.</li><li><strong>ServiceNow Autonomous Workforce:</strong> AI Specialists completing end-to-end work under defined roles, authority, policy, traces, and escalation.</li></ol><p>Marketing terms such as “first,” “limitless workforce,” or “fully autonomous” are not treated as research conclusions. This report analyzes the disclosed architecture mechanisms.</p><h2 id="weekly-highlights" tabindex="-1">Weekly Highlights <a class="header-anchor" href="#weekly-highlights" aria-label="Permalink to &quot;Weekly Highlights&quot;">​</a></h2><h3 id="_1-agents-are-moving-inside-transactional-systems" tabindex="-1">1. Agents are moving inside transactional systems <a class="header-anchor" href="#_1-agents-are-moving-inside-transactional-systems" aria-label="Permalink to &quot;1. Agents are moving inside transactional systems&quot;">​</a></h3><p>Oracle explicitly contrasts Fusion Agentic Applications with disconnected external Agent layers. They operate directly on Fusion business objects, workflows, tools, policies, and approvals while inheriting security and audit controls.</p><p>Salesforce similarly grounds Agentforce in enterprise data, metadata, flows, and existing application logic. ServiceNow connects AI Specialists to workflows and systems of record.</p><p>The direction is moving from “an Agent calls several APIs” toward “an Agent becomes a governed execution subject inside the business system.”</p><h3 id="_2-the-product-unit-is-shifting-from-agent-to-agentic-application-or-workforce" tabindex="-1">2. The product unit is shifting from Agent to Agentic Application or Workforce <a class="header-anchor" href="#_2-the-product-unit-is-shifting-from-agent-to-agentic-application-or-workforce" aria-label="Permalink to &quot;2. The product unit is shifting from Agent to Agentic Application or Workforce&quot;">​</a></h3><p>Oracle’s newer unit is not a standalone Agent, but an Agentic Application composed of specialized Agent teams, user experiences, workflows, tools, policy, approval, and runtime assets.</p><p>ServiceNow uses Autonomous Workforce and AI Specialist. Salesforce uses Digital Labor Platform. The common shift is that vendors increasingly sell systems that complete business outcomes rather than abstract Agent frameworks.</p><h3 id="_3-deterministic-process-and-probabilistic-intelligence-are-being-combined" tabindex="-1">3. Deterministic process and probabilistic intelligence are being combined <a class="header-anchor" href="#_3-deterministic-process-and-probabilistic-intelligence-are-being-combined" aria-label="Permalink to &quot;3. Deterministic process and probabilistic intelligence are being combined&quot;">​</a></h3><p>None of the three systems gives unlimited execution authority to a model:</p><ul><li>Oracle retains business objects, role-based access, approvals, and auditable actions;</li><li>Salesforce emphasizes hybrid reasoning, flows, business logic, and security;</li><li>ServiceNow places AI Specialists inside deterministic workflows, policy, and human escalation.</li></ul><p>Probabilistic intelligence interprets and decides. Deterministic systems control authority, state, transactions, and completion boundaries.</p><h2 id="cross-analysis" tabindex="-1">Cross Analysis <a class="header-anchor" href="#cross-analysis" aria-label="Permalink to &quot;Cross Analysis&quot;">​</a></h2><h3 id="enterprise-execution-platform-comparison" tabindex="-1">Enterprise execution platform comparison <a class="header-anchor" href="#enterprise-execution-platform-comparison" aria-label="Permalink to &quot;Enterprise execution platform comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Architecture dimension</th><th>Oracle Fusion Agentic Applications</th><th>Salesforce Agentforce</th><th>ServiceNow Autonomous Workforce</th></tr></thead><tbody><tr><td>Primary positioning</td><td>Fusion-native Agentic Applications</td><td>Enterprise digital labor platform</td><td>Enterprise AI Specialist workforce</td></tr><tr><td>Core data context</td><td>Fusion business objects, knowledge, APIs</td><td>Data 360, CRM data, metadata</td><td>ServiceNow data, CMDB, enterprise connections</td></tr><tr><td>Work execution</td><td>Agent teams + workflow + tools</td><td>Reasoning + skills + flows + actions</td><td>Specialists + deterministic workflow</td></tr><tr><td>Authority foundation</td><td>Fusion role-based access</td><td>Salesforce trust, permissions, business logic</td><td>Scope, authority, policy, escalation</td></tr><tr><td>Human intervention</td><td>Approval and process nodes</td><td>Human steps inside flows and business rules</td><td>Explicit human escalation conditions</td></tr><tr><td>Audit and observation</td><td>Logged actions, validation, auditability</td><td>Observability, security, business records</td><td>Traces, Control Tower, workflow history</td></tr><tr><td>Third-party connection</td><td>Connectors, APIs, third-party Agents</td><td>External systems, MuleSoft, open connections</td><td>Cross-cloud, model, and system orchestration</td></tr><tr><td>Principal strength</td><td>Transaction-system-native execution</td><td>CRM, data, and automation integration</td><td>Workflow, IT governance, runtime control</td></tr></tbody></table><p><strong>Note:</strong> This is a qualitative synthesis of official capability descriptions, not a performance or market-share benchmark.</p><h3 id="architecture-shift-from-record-to-execution" tabindex="-1">Architecture shift from record to execution <a class="header-anchor" href="#architecture-shift-from-record-to-execution" aria-label="Permalink to &quot;Architecture shift from record to execution&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Traditional System of Record</span></span>
<span class="line"><span>  data + business objects + authority + transaction history</span></span>
<span class="line"><span>                         ↓</span></span>
<span class="line"><span>                Agentic Execution Layer</span></span>
<span class="line"><span>  reasoning + skill + tool + workflow + Agent team</span></span>
<span class="line"><span>                         ↓</span></span>
<span class="line"><span>             Governed Business Outcome</span></span>
<span class="line"><span>  approval + transaction + evidence + audit + recovery</span></span></code></pre></div><p><em>Diagram: joinwell52 Research Center synthesis from Oracle, Salesforce, and ServiceNow materials.</em></p><h3 id="structured-capability-evidence" tabindex="-1">Structured capability evidence <a class="header-anchor" href="#structured-capability-evidence" aria-label="Permalink to &quot;Structured capability evidence&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Observable structure</th><th style="text-align:right;">Oracle</th><th style="text-align:right;">Salesforce</th><th style="text-align:right;">ServiceNow</th></tr></thead><tbody><tr><td>Explicit business data / objects</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>Explicit workflow / flow</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>Explicit inherited authority or security</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>Explicit human approval / escalation</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>Explicit audit / observation</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>Explicit multi-Agent / specialized roles</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr></tbody></table><p><code>1</code> means the structure is explicitly described in official material. It does not imply equal implementation depth or independent validation. The table demonstrates structural convergence across the three platforms.</p><h2 id="new-architecture-judgment" tabindex="-1">New Architecture Judgment <a class="header-anchor" href="#new-architecture-judgment" aria-label="Permalink to &quot;New Architecture Judgment&quot;">​</a></h2><h3 id="_1-the-durable-enterprise-agent-moat-is-business-context-not-only-model-quality" tabindex="-1">1. The durable enterprise Agent moat is business context, not only model quality <a class="header-anchor" href="#_1-the-durable-enterprise-agent-moat-is-business-context-not-only-model-quality" aria-label="Permalink to &quot;1. The durable enterprise Agent moat is business context, not only model quality&quot;">​</a></h3><p>Enterprise execution depends on accumulated business objects, role permissions, policies, approvals, transaction history, and audit. An external Agent must rebuild these controls if it operates outside the enterprise system.</p><h3 id="_2-agentic-application-is-closer-to-a-purchasable-product-than-a-generic-agent" tabindex="-1">2. Agentic Application is closer to a purchasable product than a generic Agent <a class="header-anchor" href="#_2-agentic-application-is-closer-to-a-purchasable-product-than-a-generic-agent" aria-label="Permalink to &quot;2. Agentic Application is closer to a purchasable product than a generic Agent&quot;">​</a></h3><p>Organizations buy completed recruitment, procurement approval, service resolution, and sales progression—not a larger number of Agents. Agentic Applications define the boundary through outcomes, process, and responsibility.</p><h3 id="_3-a-system-of-execution-still-requires-a-deterministic-shell" tabindex="-1">3. A System of Execution still requires a deterministic shell <a class="header-anchor" href="#_3-a-system-of-execution-still-requires-a-deterministic-shell" aria-label="Permalink to &quot;3. A System of Execution still requires a deterministic shell&quot;">​</a></h3><p>AI may propose plans, select tools, and handle exceptions. Authority, state transition, approval, transaction commit, evidence, and completion judgment still require deterministic control.</p><h3 id="_4-native-integration-and-open-runtime-are-in-tension" tabindex="-1">4. Native integration and open runtime are in tension <a class="header-anchor" href="#_4-native-integration-and-open-runtime-are-in-tension" aria-label="Permalink to &quot;4. Native integration and open runtime are in tension&quot;">​</a></h3><p>Native platforms provide stronger context, security, and audit but create vendor dependency. Open runtimes provide flexibility but must independently solve identity, business objects, authority, recovery, and audit. SME-oriented systems need a minimum viable balance between the two.</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>This report does not modify TMPA publications. It provides research input that enterprise execution is not merely a message or tool call, but a reconstructable work record across Authority, Lifecycle, Reference, Event, Evidence, and Governance Judgment.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>A Digital Employee should be packaged as a position- and outcome-oriented Agentic Work Application rather than a bare Agent. Its minimum composition is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Position</span></span>
<span class="line"><span>+ Work Catalog</span></span>
<span class="line"><span>+ Workflow</span></span>
<span class="line"><span>+ Runtime</span></span>
<span class="line"><span>+ Tool / Skill</span></span>
<span class="line"><span>+ Authority</span></span>
<span class="line"><span>+ Human Escalation</span></span>
<span class="line"><span>+ Evidence / Evaluation</span></span></code></pre></div><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu should not replicate the full Oracle, Salesforce, or ServiceNow application estate. Its opportunity is an independent, lightweight, SME-first work runtime that brings external business systems, browser and Windows operations, and APIs into one WorkOrder, recovery, evidence, and completion-gate model.</p><h2 id="next-week-research" tabindex="-1">Next Week Research <a class="header-anchor" href="#next-week-research" aria-label="Permalink to &quot;Next Week Research&quot;">​</a></h2><ol><li>Study SAP Joule Agents and Microsoft Copilot Studio as Agentic Application patterns.</li><li>Compare recovery in native transactional systems and external runtimes.</li><li>Define a minimum portable Agentic Application contract.</li><li>Study the gap between business completion and Agent-declared completion.</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Oracle, <strong>Oracle Introduces Fusion Agentic Applications</strong>: <a href="https://www.oracle.com/uk/news/announcement/oracle-introduces-fusion-agentic-applications-2026-03-24/" target="_blank" rel="noreferrer">https://www.oracle.com/uk/news/announcement/oracle-introduces-fusion-agentic-applications-2026-03-24/</a></li><li>Oracle, <strong>AI-Native Builder Experience for Fusion Agentic Applications</strong>: <a href="https://www.oracle.com/europe/news/announcement/oracle-introduces-ai-native-builder-experience-2026-07-14/" target="_blank" rel="noreferrer">https://www.oracle.com/europe/news/announcement/oracle-introduces-ai-native-builder-experience-2026-07-14/</a></li><li>Oracle Documentation, <strong>Overview of AI Agent Studio</strong>: <a href="https://docs.oracle.com/en/cloud/saas/fusion-ai/26c/aiaas/overview.html" target="_blank" rel="noreferrer">https://docs.oracle.com/en/cloud/saas/fusion-ai/26c/aiaas/overview.html</a></li><li>Oracle Documentation, <strong>Key Capabilities of AI Agent Studio</strong>: <a href="https://docs.oracle.com/en/cloud/saas/fusion-ai/26b/aiaas/key-capabilities.html" target="_blank" rel="noreferrer">https://docs.oracle.com/en/cloud/saas/fusion-ai/26b/aiaas/key-capabilities.html</a></li><li>Salesforce, <strong>Agentforce 360 Platform</strong>: <a href="https://www.salesforce.com/platform/agentforce-platform" target="_blank" rel="noreferrer">https://www.salesforce.com/platform/agentforce-platform</a></li><li>Salesforce, <strong>Introducing Agentforce 2.0</strong>: <a href="https://www.salesforce.com/news/press-releases/2024/12/17/agentforce-2-0-announcement/" target="_blank" rel="noreferrer">https://www.salesforce.com/news/press-releases/2024/12/17/agentforce-2-0-announcement/</a></li><li>ServiceNow, <strong>Autonomous Workforce</strong>: <a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx</a></li><li>ServiceNow, <strong>AI Control Tower</strong>: <a href="https://www.servicenow.com/products/ai-control-tower.html" target="_blank" rel="noreferrer">https://www.servicenow.com/products/ai-control-tower.html</a></li></ol>`,52))])}const b=a(l,[["render",c]]);export{f as __pageData,b as default};
